/* Navigation and shared UI */
function go(page){if(page==='how'){openTour(0);return}const target=document.getElementById('page-'+page);if(!target){toast('This section is not available yet.');return}document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));target.classList.add('active');document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.getElementById('crumb').textContent=({overview:'Dashboard',match:'Deal Matching',memo:'Memo Studio',pipeline:'Outreach',samples:'Demo deals',news:'Research updates',equity:'Research',quant:'Quant Lab',about:'About the Founder',how:'How it works'})[page];window.scrollTo({top:0,behavior:'smooth'});document.querySelector('.sidebar').classList.remove('mobile-open');if(page==='pipeline')renderPipeline();if(page==='news'&&!window._mandateNewsLoaded){window._mandateNewsLoaded=true;loadLiveHeadlines(false)}}
document.querySelectorAll('.nav button').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));
function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.style.display='block';clearTimeout(window._toast);window._toast=setTimeout(()=>t.style.display='none',3200)}
function setProfile(d){['Company','Sector','Geo','Raise','Revenue','Ebitda','Type','Context'].forEach(k=>{let el=document.getElementById('p'+k);if(el)el.value=d[({Company:'name',Sector:'sector',Geo:'geo',Raise:'raise',Revenue:'revenue',Ebitda:'ebitda',Type:'type',Context:'context'})[k]]||''});document.getElementById('dealText').value=d.text||'';document.getElementById('profileStatus').textContent='PROFILE LOADED';currentDeal=d;document.getElementById('fileStatus').textContent='Loaded: '+d.name+' · Fictional sample';}
function loadSample(id){let d=sampleDeals[id];setProfile(d);go('match');analyzeDeal();toast('Sample deal loaded. Review the ranked matches.')}
function clearDeal(){document.getElementById('dealText').value='';['pCompany','pRaise','pRevenue','pEbitda','pContext'].forEach(id=>document.getElementById(id).value='');['pSector','pGeo','pType'].forEach(id=>document.getElementById(id).value='');currentDeal=null;currentMatches=[];document.getElementById('matchResults').innerHTML='<div class="empty"><strong>Your match list is waiting.</strong>Load a sample or analyze a one-pager to rank potential capital providers.</div>';document.getElementById('matchCaption').textContent='Your ranked list will appear here after analysis.'}
function normalize(s){return (s||'').toLowerCase()}
function parseAmount(s){if(!s)return null;let m=String(s).replace(/,/g,'').match(/([\d.]+)\s*(billion|bn|b|million|mm|m|k)?/i);if(!m)return null;let n=Number(m[1]);let u=(m[2]||'').toLowerCase();if(['billion','bn','b'].includes(u))n*=1000;else if(['k'].includes(u))n/=1000;return n}
function extractProfile(text){let t=text||'',low=t.toLowerCase();let d={name:'',sector:'',geo:'',raise:'',revenue:'',ebitda:'',type:'',context:'',text:t};let first=(t.split(/\n/).map(x=>x.trim()).find(x=>x.length>3&&!/confidential sample teaser/i.test(x))||'').replace(/[—-].*/,'').trim();d.name=first.slice(0,70);
const sectors=[['Sports',/sports|mlb|nba|nfl|franchise|media rights|professional sports/],['Healthcare Services',/veterinar|clinic|healthcare|medical|physician|health services/],['Packaging',/packaging/],['Technology',/technology|software|saas|water monitoring|artificial intelligence|ai platform/],['Energy & Infrastructure',/infrastructure|cold.chain|logistics|fleet|energy|project finance/],['Real Estate',/real estate|multifamily|property|residential|commercial real estate/],['Food & Agriculture',/agricultur|food production|cocoa|farm/],['Business Services',/business services|outsourc|facility services/],['Consumer',/consumer brand|consumer products|retail/]];for(let [s,re] of sectors){if(re.test(low)){d.sector=s;break}}
if(/south africa|south african|johannesburg|cape town|sub.saharan africa|africa/i.test(t))d.geo=/south africa/i.test(t)?'South Africa':'Sub-Saharan Africa';else if(/europe|uk |united kingdom|germany|france/i.test(t))d.geo='Europe';else if(/global|international/i.test(t))d.geo='Global';else if(/north america|u\.s\.|united states|usa|southeast|midwest|new york|california/i.test(t))d.geo='United States';
function findMoney(regex){let m=t.match(regex);return m?m[1].replace(/\s+/g,'').replace(/million/i,'M').replace(/billion/i,'B'):''}
d.raise=findMoney(/(?:seeking|raise|raising|capital need|capital raise|investment of|equity capital of|financing of)\s*(?:approximately|about|up to)?\s*\$?\s*([\d,.]+\s*(?:million|billion|M|B|mm|m|bn)?)/i);
d.revenue=findMoney(/(?:revenue|sales)\s*(?:of|:|was|reached)?\s*\$?\s*([\d,.]+\s*(?:million|billion|M|B|mm|m|bn)?)/i);
d.ebitda=findMoney(/EBITDA\s*(?:of|:|was|reached)?\s*\$?\s*([\d,.]+\s*(?:million|billion|M|B|mm|m|bn)?)/i);
if(/fund investment|access fund|limited partner|\blp interest/i.test(t))d.type='Fund Investment / LP Interest';else if(/late.stage private equity|late.stage pe/i.test(t))d.type='Late-Stage PE';else if(/mezzanine/i.test(t))d.type='Mezzanine Debt';else if(/senior debt|term loan|debt financing/i.test(t))d.type='Senior Debt';else if(/project finance/i.test(t))d.type='Project Finance';else if(/control|buyout|acquisition capital/i.test(t))d.type='Buyout / Control Equity';else if(/minority/i.test(t))d.type='Minority Equity';else if(/growth equity|growth capital/i.test(t))d.type='Growth Equity';else if(/real estate equity/i.test(t))d.type='Real Estate Equity';else if(/structured capital|flexible capital/i.test(t))d.type='Flexible Capital';
d.context=(t.match(/(?:investment highlights|key highlights|transaction|growth opportunities|use of proceeds)\s*[:\-]?\s*([^\n.]+(?:\.[^\n.]+)?)/i)||[])[1]||'';return d}
function dealFromFields(){return {name:document.getElementById('pCompany').value.trim(),sector:document.getElementById('pSector').value,geo:document.getElementById('pGeo').value,raise:document.getElementById('pRaise').value.trim(),revenue:document.getElementById('pRevenue').value.trim(),ebitda:document.getElementById('pEbitda').value.trim(),type:document.getElementById('pType').value,context:document.getElementById('pContext').value.trim(),text:document.getElementById('dealText').value}}
function analyzeDeal(){let t=document.getElementById('dealText').value.trim();let d=extractProfile(t);let f=dealFromFields();Object.keys(f).forEach(k=>{if(f[k])d[k]=f[k]});if(!d.name&&!t){toast('Paste a teaser or load a sample deal first.');return}currentDeal=d;setProfile(d);runMatches();dealCount++;document.getElementById('statDeals').textContent=dealCount;go('match')}
/* Investor matching and scoring */
function runMatches(){let d=dealFromFields();if(!d.name){toast('Add a company name or load a sample deal.');return}d.text=document.getElementById('dealText').value;currentDeal=d;let amount=parseAmount(d.raise);let ranked=investors.map((inv,i)=>{let reasons=[],misses=[],score=32;
if(d.sector&&inv.sector.includes(d.sector)){score+=27;reasons.push('Sector focus aligns')}else if(d.sector){score-=9;misses.push('Sector fit unclear')}
if(d.geo&&inv.geo.some(g=>g===d.geo||g==='Global'||(d.geo==='United States'&&g==='North America'))){score+=18;reasons.push('Geography in stated remit')}else if(d.geo){score-=6;misses.push('Geography needs confirmation')}
if(d.type&&inv.structures.includes(d.type)){score+=18;reasons.push('Capital structure aligns')}else if(d.type){score-=5;misses.push('Structure not explicitly listed')}
if(amount!==null){if(amount>=inv.min&&amount<=inv.max){score+=15;reasons.push('Raise fits illustrative ticket range')}else if(amount<inv.min){score-=9;misses.push('Raise below stated ticket range')}else{score-=6;misses.push('Raise above stated ticket range')}}else misses.push('Confirm target check size');
if(/recurring|contracted|profitable|cash.flow/i.test(d.context+' '+d.text)&&/credit|lending|capital|growth/i.test(inv.type)){score+=3}
score=Math.max(22,Math.min(97,score));return {...inv,score,reasons,misses,id:inv.name.replace(/\W/g,'').toLowerCase(),status:'To contact',deal:d.name,added:false}}).sort((a,b)=>b.score-a.score);
let offSector=ranked.filter(x=>d.sector&&!x.sector.includes(d.sector)).length;currentMatches=d.sector?ranked.filter(x=>x.sector.includes(d.sector)):ranked;currentMatches=currentMatches.map(enrichInvestorProfile);matchCount++;document.getElementById('statMatches').textContent=matchCount;document.getElementById('matchCaption').textContent=`${currentMatches.length} sector-aligned fictional capital providers for ${d.name}. ${offSector} off-sector profiles withheld to reduce irrelevant outreach.`;renderMatches();document.getElementById('profileStatus').textContent='MATCHES READY';if(!currentMatches.length)document.getElementById('matchResults').innerHTML='<div class="empty"><strong>No sector-aligned profiles in this sample universe.</strong>Off-sector investors have been withheld to prevent irrelevant outreach. Add verified mandate data or broaden the deal sector only if justified.</div>'}
function enrichInvestorProfile(x){const baseMap={'Alder Ridge Capital':'New York, United States','Northbank Partners':'Boston, United States','Cedar Gate Credit':'Chicago, United States','Meridian Industrial Growth':'London, United Kingdom','Juniper Health Investors':'Boston, United States','Atlas Emerging Markets':'Johannesburg, South Africa','Granite Peak Direct Lending':'New York, United States','Lighthouse Climate Ventures':'San Francisco, United States','Willow Creek Capital':'Chicago, United States','Summit Equipment Finance':'New York, United States','Bluehaven Family Capital':'New York, United States','Redwood Infrastructure Partners':'London, United Kingdom','Silverline Special Situations':'New York, United States','Evergreen Consumer & Industry':'Chicago, United States','Pioneer Water & Climate Fund':'San Francisco, United States','Stonebridge Capital Solutions':'Johannesburg, South Africa','Crownwell Medical Growth':'Boston, United States','Ironwood Asset Finance':'Chicago, United States','Mosaic Impact Partners':'Global / distributed','Westfield Private Capital':'New York, United States','Horizon Growth Partners':'San Francisco, United States','Parkview Real Assets':'New York, United States','Fairmont Strategic Holdings':'Global / distributed'};let name=x.name;let home=baseMap[name]||(x.geo.includes('South Africa')||x.geo.includes('Sub-Saharan Africa')?'Johannesburg, South Africa':x.geo.includes('Europe')?'London, United Kingdom':x.geo.includes('North America')||x.geo.includes('United States')?'New York, United States':'Global / distributed');let expansion=x.geo.filter(g=>g!=='Global'&&!g.includes('United States'));if(x.geo.includes('Global'))expansion.push('Selective global opportunities');let activity=x.sector.slice(0,2).join(' and ');let activityType=/credit|lending|debt|finance/i.test(x.type)?'Illustrative activity pattern: senior or structured financing for businesses with cash flow, collateral or identifiable repayment sources.':/family office/i.test(x.type)||/family/i.test(x.type)?'Illustrative activity pattern: patient direct investments, co-investments and flexible ownership structures.':'Illustrative activity pattern: screening and investment exposure across '+activity+' opportunities, consistent with the sample mandate shown.';return {...x,base:home,history:`Illustrative profile: ${x.type.toLowerCase()} strategy with a stated focus on ${x.sector.slice(0,3).join(', ')}.`,investmentGeography:x.geo.join(', '),expansion:expansion.length?expansion.join(', '):'No separate expansion market stated',typicalApproach:x.structures.join(', '),pastActivity:activityType+' This is a demo research field, not a claim about a real firm or completed transaction.'}}
