function continueLeadEmail(){const to=document.getElementById('leadEmailTo').value.trim();const subject=document.getElementById('leadEmailSubject').value.trim();const body=document.getElementById('leadEmailBody').value; if(!to||!/^\S+@\S+\.\S+$/.test(to)){toast('Enter a verified recipient email address first.');document.getElementById('leadEmailTo').focus();return}const url='mailto:'+encodeURIComponent(to)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);closeLeadEmail();window.location.href=url;toast('Your email app should open with the draft ready to review.');}
