function pipelineKey(x){return (x.id+'::'+(x.deal||currentDeal?.name||'Untitled deal')).toLowerCase()}
function addPipeline(id){let x=currentMatches.find(y=>y.id===id);if(!x)return;let key=pipelineKey(x);if(pipeline.some(p=>p.pipelineKey===key)){toast('This investor is already tracked for this deal.');return}pipeline.push({...x,pipelineKey:key,dealSector:currentDeal?.sector||dealFromFields().sector||'',added:true,leadTemp:'Cold',notes:'',date:new Date().toLocaleDateString(),status:'To contact'});renderMatches();renderPipeline();toast('Investor added to this deal’s pipeline.')}
function renderPipeline(){let c=pipeline.length;document.getElementById('pipeCount').textContent=c;document.getElementById('pipeTodo').textContent=pipeline.filter(p=>p.status==='To contact').length;document.getElementById('pipeConvo').textContent=pipeline.filter(p=>['Contacted','In diligence','Interested'].includes(p.status)).length;document.getElementById('pipeClosed').textContent=pipeline.filter(p=>['Passed','Closed'].includes(p.status)).length;let root=document.getElementById('pipelineTable');if(!c){root.className='empty';root.innerHTML='<strong>No leads added yet.</strong>Run a match and click “Add to pipeline” on any investor.';return}root.className='tablewrap';root.innerHTML=`<table><thead><tr><th>Investor</th><th>Deal</th><th>Sector</th><th>Fit</th><th>Relationship</th><th>Status</th><th>Notes / next step</th><th></th></tr></thead><tbody>${pipeline.map(p=>`<tr><td><div class="investor"><div class="investorlogo">${p.name[0]}</div><div><strong>${p.name}</strong><small>${p.type}</small></div></div></td><td>${p.deal||'—'}</td><td>${p.dealSector||'—'}</td><td class="score">${p.score}/100</td><td><select class="field" style="min-width:105px;padding:7px" onchange="updatePipeline('${p.pipelineKey}','leadTemp',this.value)">${['Cold','Warm','Hot','Do not contact'].map(s=>`<option ${p.leadTemp===s?'selected':''}>${s}</option>`).join('')}</select></td><td><select class="field" style="min-width:120px;padding:7px" onchange="updatePipeline('${p.pipelineKey}','status',this.value)">${['To contact','Contacted','Interested','In diligence','Passed','Closed'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><input class="field" style="min-width:180px;padding:7px" value="${(p.notes||'').replace(/"/g,'&quot;')}" placeholder="Next step / response" onchange="updatePipeline('${p.pipelineKey}','notes',this.value)"/></td><td><button class="btn small primary" onclick="draftIntro('${p.id}')">Contact lead ↗</button><button class="btn small" style="margin-top:5px" onclick="removePipeline('${p.pipelineKey}')">Remove</button></td></tr>`).join('')}</tbody></table>`}
function addManualLead(){const name=document.getElementById('manualLeadName').value.trim();if(!name){toast('Enter a firm or investor name first.');document.getElementById('manualLeadName').focus();return}const id='manual-'+Date.now();const x={id,name,type:document.getElementById('manualLeadType').value,base:document.getElementById('manualLeadBase').value.trim()||'Not provided',email:document.getElementById('manualLeadEmail').value.trim(),score:0,ticket:'Not researched',structures:[],reasons:[],misses:[],deal:currentDeal?.name||'Unassigned',dealSector:currentDeal?.sector||'',pipelineKey:id+'::'+(currentDeal?.name||'Unassigned'),added:true,leadTemp:'Cold',notes:document.getElementById('manualLeadNotes').value.trim(),date:new Date().toLocaleDateString(),status:'To contact',history:'Manually added lead. Verify the firm’s mandate and public information.',investmentGeography:'Not researched',expansion:'Not researched',typicalApproach:'Not researched',pastActivity:'Not researched'};pipeline.push(x);['manualLeadName','manualLeadBase','manualLeadEmail','manualLeadNotes'].forEach(k=>document.getElementById(k).value='');renderPipeline();toast('Lead added to your pipeline.');}
function updatePipeline(id,k,v){let p=pipeline.find(x=>x.pipelineKey===id);if(p)p[k]=v;renderPipeline()}
function removePipeline(id){pipeline=pipeline.filter(p=>p.pipelineKey!==id);renderPipeline();renderMatches()}
