async function extractFile(file){let name=file.name.toLowerCase();if(name.endsWith('.txt')||name.endsWith('.md'))return await file.text();if(name.endsWith('.pdf')){if(!window.pdfjsLib){await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'}let ab=await file.arrayBuffer(),pdf=await pdfjsLib.getDocument({data:ab}).promise,txt='';for(let i=1;i<=pdf.numPages;i++){let pg=await pdf.getPage(i),c=await pg.getTextContent();txt+=c.items.map(x=>x.str).join(' ')+'\n'}return txt}
if(name.endsWith('.docx')){if(!window.mammoth)await loadScript('https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.8.0/mammoth.browser.min.js');let ab=await file.arrayBuffer();let out=await mammoth.extractRawText({arrayBuffer:ab});return out.value}
if(name.endsWith('.pptx')){if(!window.JSZip)await loadScript('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js');let zip=await JSZip.loadAsync(await file.arrayBuffer());let slides=Object.keys(zip.files).filter(k=>/^ppt\/slides\/slide\d+\.xml$/.test(k)).sort((a,b)=>parseInt(a.match(/slide(\d+)/)[1])-parseInt(b.match(/slide(\d+)/)[1]));let out='';for(let s of slides){let xml=await zip.file(s).async('text'),doc=new DOMParser().parseFromString(xml,'text/xml');out+=`\\n--- ${s.split('/').pop().replace('.xml','').toUpperCase()} ---\\n`+Array.from(doc.getElementsByTagName('a:t')).map(n=>n.textContent).join(' ')+'\\n'}return out}
if(name.endsWith('.ppt'))throw new Error('Legacy .ppt files are not supported. Please save the presentation as .pptx and upload again.');
throw new Error('File type not supported in this demo. Use PDF, PPTX, DOCX or TXT.')}
function loadScript(src){return new Promise((resolve,reject)=>{let s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>reject(new Error('Could not load document parser. Check your internet connection or paste the text instead.'));document.head.appendChild(s)})}
function bindUpload(inputId,where){let input=document.getElementById(inputId);input.addEventListener('change',async()=>{if(input.files[0])await handleFile(input.files[0],where)});let drop=document.getElementById(where==='deal'?'matchDrop':where==='memo'?'memoDrop':'homeDrop');if(drop){drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',async e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files[0])await handleFile(e.dataTransfer.files[0],where)})}}
async function handleFile(file,where){try{toast('Reading '+file.name+'…');let txt=await extractFile(file);activeFileName=file.name;fileTextCache=txt;if(!txt.trim())throw new Error('No selectable text found. Try a text-based PDF or paste the text manually.');if(where==='memo'){document.getElementById('memoText').value=txt;document.getElementById('memoFileStatus').textContent=`Loaded ${file.name} · ${txt.length.toLocaleString()} characters extracted`;go('memo');toast('Source text extracted. Review it before generating the memo.')}else{document.getElementById('dealText').value=txt;let d=extractProfile(txt);setProfile(d);document.getElementById('fileStatus').textContent=`Loaded ${file.name} · ${txt.length.toLocaleString()} characters extracted`;go('match');toast('Deal text extracted. Review the profile and run matching.')}}catch(e){toast(e.message||'Could not read this file. Try pasting its text instead.');}}
const tourSteps=[{label:'WELCOME',title:'Capital matching, with more context.',body:'Mandate is a concept for helping investment analysts and deal teams move from a company opportunity to a more relevant shortlist of capital partners.',extra:'The goal: less time organizing scattered information, and more time reviewing fit, preparing diligence and making thoughtful outreach.'},{label:'THE WORKFLOW',title:'From deal profile to a useful shortlist.',body:'Use Deal Matching to load a sample opportunity, then compare sector, geography, capital sought and structure against sample investor mandates.',extra:'Filter by target investment geography and investor headquarters. Open Investor profile for strategy, base, reach and illustrative background.'},{label:'LEADS & OUTREACH',title:'Organize leads and prepare an introduction.',body:'Add promising profiles to Leads & Pipeline, track next steps, and use Contact lead to review a personalized draft before opening your email app.',extra:'The draft is editable. Continue opens your default email app with recipient, subject and body filled in. You review and send it yourself.'},{label:'IMPORTANT · MOCKUP',title:'A prototype, not the live platform.',body:'This demonstration uses fictional investor profiles and local sample data. It is not connected to a live investor database, verified transaction history, secure firm workspace or production AI backend.',extra:'A firm-ready version would require verified data sources, permissions, secure storage, source citations, access controls, and review of compliance and legal requirements.'},{label:'NEXT · GET IN TOUCH',title:'Want to discuss a pilot?',body:'This demo uses fictional investor profiles and is not connected to a live capital database or production AI backend.',extra:'Email: <a class=\"tour-email\" href=\"mailto:Kokoesegbedji01@gmail.com?subject=Mandate%20pilot%20discussion\">Kokoesegbedji01@gmail.com</a><br><br>A firm-ready version would require verified data sources, secure storage and permission controls.'}];let tourIndex=0;function openTour(i=0){tourIndex=Math.max(0,Math.min(i,tourSteps.length-1));renderTour();document.getElementById('productTour').classList.add('open');document.body.style.overflow='hidden'}function closeTour(){document.getElementById('productTour').classList.remove('open');document.body.style.overflow='';try{sessionStorage.setItem('mandateTourSeen','1')}catch(e){}}function renderTour(){let x=tourSteps[tourIndex];document.getElementById('tourStepLabel').textContent=`${String(tourIndex+1).padStart(2,'0')} / ${String(tourSteps.length).padStart(2,'0')} · ${x.label}`;document.getElementById('tourTitle').textContent=x.title;document.getElementById('tourBody').textContent=x.body;document.getElementById('tourExtra').innerHTML=x.extra;document.getElementById('tourProgressFill').style.width=((tourIndex+1)/tourSteps.length*100)+'%';document.getElementById('tourBack').disabled=tourIndex===0;document.getElementById('tourNext').textContent=tourIndex===tourSteps.length-1?'Finish tour ✓':'Next step →'}function tourNext(){if(tourIndex<tourSteps.length-1){tourIndex++;renderTour()}else{closeTour();toast('Tour complete. Start with a sample deal on the home dashboard.')}}function tourBack(){if(tourIndex>0){tourIndex--;renderTour()}}document.getElementById('productTour').addEventListener('click',e=>{if(e.target.id==='productTour')closeTour()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeTour();if(e.key==='ArrowRight'&&document.getElementById('productTour').classList.contains('open'))tourNext()});window.addEventListener('load',()=>{let seen=false;try{seen=sessionStorage.getItem('mandateTourSeen')==='1'}catch(e){}if(!seen)setTimeout(()=>openTour(0),450)});

