function getMetric(text,re){let m=text.match(re);return m?m[1].trim():''}
/* Memo Studio: one-pager and investment memo generation */
function generateOnePager(){let text=document.getElementById('memoText').value.trim();if(!text){toast('Upload a deck or paste source text first.');return}let lines=text.split(/\n+/).map(x=>x.trim()).filter(Boolean);let title=(lines.find(x=>/NORTHSTAR|SOLTERRA|HARBORPOINT|BLUECURRENT|TERRACOCOA/i.test(x))||lines[0]||'Investment Opportunity').replace(/—.*$/,'').replace(/SAMPLE PITCH DECK TEXT/i,'').trim();let rev=[...text.matchAll(/FY20\d\d[^\n]{0,50}?revenue[:\s]*\$?([\d,.]+\s*(?:M|million|mm)?)/gi)].map(m=>m[1]);let ebitda=[...text.matchAll(/FY20\d\d[^\n]{0,50}?EBITDA[:\s]*\$?([\d,.]+\s*(?:M|million|mm)?)/gi)].map(m=>m[1]);let cap=getMetric(text,/(?:seeking|capital sought|raise|raising)\s*\$?\s*([\d,.]+\s*(?:million|M|mm)?)/i)||'Not provided';let pick=(re,fallback)=>lines.filter(x=>re.test(x)).slice(0,3).join(' ')||fallback;let business=pick(/business overview|business:|manufactures|provider|platform|business model/i,'Business model and revenue streams require confirmation from company materials.');let market=pick(/market|industry|TAM|SAM|SOM|customer demand|global landscape/i,'TAM, SAM, SOM, industry growth, geographic demand and market sources not provided.');let team=pick(/management|founder|CEO|executive|leadership|team/i,'Management biographies, track record and references not provided.');let comp=pick(/competitor|competitive|market share|SWOT|differentiation/i,'Competitor set, market share and defensibility not established in source materials.');let tx=pick(/transaction|growth equity|capital sought|seeking \$/i,'Transaction structure, valuation, ownership and use of proceeds require confirmation.');let risks=lines.filter(x=>/risk|diligence|concentration|not provided|not been provided|unverified|compliance|capex|valuation|exit/i.test(x)).slice(0,3);let thesis=pick(/growth|recurring|contract|demand|expansion|competitive|customer|technology|platform|service/i,'Investment thesis is preliminary and requires evidence for growth durability, differentiation and return potential.');let exit=pick(/exit|strategic buyer|sale|IPO|multiple expansion|waterfall/i,'Potential exit routes, timing, buyer universe and return waterfall have not been established.');let disclaimer='Draft generated from supplied materials only. Facts, forecasts and management claims are not independently verified. Missing information is explicitly identified rather than assumed.';let esc=escapeHtml;let html=`<div style="max-width:850px;margin:auto;background:white;padding:24px;border:1px solid #e0e5df;border-radius:10px"><div class="memo-top"><div><div class="memo-brand">MANDATE</div><div class="memo-label">Investment opportunity · One-page screening brief</div></div><div class="memo-label">Draft · Review before sharing</div></div><h2 class="memo-title">${esc(title)}</h2><p class="memo-meta">Prepared ${new Date().toLocaleDateString()} · Based on supplied materials · Not independently verified</p><div class="memo-metrics"><div class="metric"><span>Capital sought</span><strong>${esc(cap)}</strong></div><div class="metric"><span>Latest revenue found</span><strong>${rev.length?esc(rev[rev.length-1]):'Not provided'}</strong></div><div class="metric"><span>Latest EBITDA found</span><strong>${ebitda.length?esc(ebitda[ebitda.length-1]):'Not provided'}</strong></div><div class="metric"><span>Evidence status</span><strong>Draft</strong></div></div><div class="memo-section"><h3>Executive summary and preliminary thesis</h3><p>${esc(thesis)}</p></div><div class="memo-section"><h3>Business model</h3><p>${esc(business)}</p></div><div class="memo-section"><h3>Market opportunity and competition</h3><p><strong>Market:</strong> ${esc(market)}</p><p><strong>Competitive position:</strong> ${esc(comp)}</p></div><div class="memo-section"><h3>Management and execution</h3><p>${esc(team)}</p></div><div class="memo-section"><h3>Financial performance</h3><p>${esc(rev.length?'Revenue figures extracted: '+rev.join(', '):'Historical revenue not identified in the source text.')} ${esc(ebitda.length?'EBITDA figures extracted: '+ebitda.join(', '):'Historical EBITDA not identified in the source text.')} Confirm period, currency, accounting basis, adjustments, cash flow, debt and working capital.</p></div><div class="memo-section"><h3>Transaction, valuation and use of proceeds</h3><p>${esc(tx)} Valuation method, ownership, governance, investor rights and return targets should be documented before underwriting.</p></div><div class="memo-section"><h3>Key risks and diligence priorities</h3><ul>${(risks.length?risks:['Quality of earnings and audited financials.','Customer concentration, retention and pricing power.','Regulatory, operational, legal, capex and working-capital exposure.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="memo-section"><h3>Exit considerations</h3><p>${esc(exit)}</p></div><div class="notice">${esc(disclaimer)}</div></div>`;document.getElementById('onePagerOutput').innerHTML=html+`<div class="onepager-next-step"><strong>Next step: find qualified leads for this one-pager</strong><p>Carry the deal profile into Mandate matching, review the investor shortlist, add qualified leads to your pipeline, then draft an email for each lead.</p><button class="btn primary" onclick="onePagerToQualifiedLeads()">Use this one-pager to find leads →</button></div>`;document.getElementById('onePagerCaption').textContent='Structured screening brief generated from source text · review before sharing';window.currentOnePager=html;window.currentOnePagerTitle=title;toast('Structured one-pager generated. Verify facts and fill gaps before sharing.')}
function downloadOnePager(){if(!window.currentOnePager){generateOnePager();if(!window.currentOnePager)return}const style='body{font-family:Arial,sans-serif;background:#f5f7f4;color:#203027;padding:24px;max-width:1000px;margin:auto}.memo-top{display:flex;justify-content:space-between;border-bottom:2px solid #18392a;padding-bottom:15px}.memo-brand{font-family:Georgia,serif;font-size:25px}.memo-label{font-size:10px;letter-spacing:1.5px;color:#8b7652;text-transform:uppercase}.memo-title{font-family:Georgia,serif;font-size:29px;font-weight:400}.memo-meta{font-size:11px;line-height:1.8;color:#303b34}.memo-paper{color:#17251f}.memo-paper strong,.metric strong,.memo-title{color:#111b15}.memo-section p,.memo-section li{color:#26342b}.memo-label{color:#57472d}.memo-metrics{display:flex;gap:8px}.metric{background:#f5f8f5;padding:12px;flex:1}.metric span,.metric strong{display:block}.metric span{font-size:10px}.metric strong{font-size:18px;margin-top:5px}.memo-section{margin:20px 0}.memo-section h3{font-size:11px;color:#315b43;border-bottom:1px solid #e6ebe6;padding-bottom:7px}.memo-section p,.memo-section li{font-size:11px;line-height:1.7}.notice{border:1px solid #e8dcc2;background:#fcf8ef;padding:10px;font-size:10px}';const html='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mandate One-pager</title><style>'+style+'</style></head><body>'+window.currentOnePager+'</body></html>';downloadBlob(html,'mandate-one-pager-draft.html','text/html')}
