function generateMemo(){let text=document.getElementById('memoText').value.trim();if(!text){toast('Upload a PowerPoint or paste source text first.');return}let lines=text.split(/\n+/).map(x=>x.trim()).filter(Boolean);let first=lines.find(x=>!/slide\s*\d+/i.test(x)&&x.length>4)||'Investment opportunity';let title=(lines.find(x=>/NORTHSTAR|SOLTERRA|HARBORPOINT|BLUECURRENT|TERRACOCOA/i.test(x))||first).split(/[—:|]/)[0].replace(/SAMPLE PITCH DECK TEXT/i,'').trim();if(title.length>90)title=title.slice(0,90);let revs=[...text.matchAll(/(?:FY20\d\d\s*)?revenue[:\s]*\$?\s*([\d,.]+\s*(?:million|M|mm)?)/gi)].map(m=>m[1]);let ebs=[...text.matchAll(/(?:FY20\d\d\s*)?EBITDA[:\s]*\$?\s*([\d,.]+\s*(?:million|M|mm)?)/gi)].map(m=>m[1]);let capital=getMetric(text,/(?:seeking|raise|raising|capital sought|capital of)\s*(?:approximately|about)?\s*\$?\s*([\d,.]+\s*(?:million|M|mm)?)/i)||'Not provided';let prof=extractProfile(text);let sector=prof.sector||'Not specified';let geo=prof.geo||'Not specified';let audience=document.getElementById('memoAudience').value,depth=document.getElementById('memoDepth').value;let esc=escapeHtml;let pick=(re,fallback,n=5)=>lines.filter(x=>re.test(x)).slice(0,n);let risks=pick(/risk|diligence|concentration|not provided|not been provided|unverified|compliance|capex|valuation|exit|regulatory|working capital/i,'');if(!risks.length)risks=['Quality of earnings and financial statement reliability require confirmation.','Customer concentration, retention and pricing power require analysis.','Regulatory, operational, legal and execution risks require assessment.'];let financials=pick(/revenue|EBITDA|margin|growth|retention|customer|capital sought|seeking|cash flow|debt|working capital/i,'');let thesis=pick(/growth|recurring|contract|demand|expansion|competitive|customer|technology|platform|service|capacity/i,'');let company=pick(/business|company|provider|platform|model|service|product|operat|manufactur/i,'Business model, products, customers, pricing and revenue streams require confirmation.',5);let management=pick(/management|founder|CEO|executive|leadership|team|succession/i,'Management biographies, relevant operating track record, incentives, references and succession coverage were not identified in the supplied source.',4);let market=pick(/market|industry|TAM|SAM|SOM|global|competitor|share|regulat|customer demand/i,'No sufficient sourced market sizing, growth forecast, customer segmentation or independent industry study was identified. Build TAM/SAM/SOM from a transparent methodology and cite the original sources.',6);let competition=pick(/competitor|competitive|market share|SWOT|differentiation|substitute/i,'Competitor names, market shares, customer win/loss evidence, switching costs and relative pricing were not established in the supplied source.',5);let growth=pick(/growth plan|expansion|proceeds|capacity|acquisition|add-on|capex|investment plan/i,'Growth plan, capital requirements, milestone timing and operational capacity need a bottom-up build.',5);let transaction=pick(/transaction|valuation|ownership|capital sought|seeking|liquidation|governance|security|terms|proceeds/i,'Valuation, proposed security, ownership offered, governance, investor rights, dilution and detailed use of proceeds were not provided.',6);let exit=pick(/exit|strategic buyer|IPO|sale|waterfall|return|IRR|MOIC/i,'Exit scenarios, likely buyer universe, holding period, exit multiples and investor return waterfall have not been provided.');let alltext=text.toLowerCase();let metricCards=`<div class="memo-metrics"><div class="metric"><span>Capital sought</span><strong>${esc(capital)}</strong></div><div class="metric"><span>Latest revenue found</span><strong>${esc(revs.length?revs[revs.length-1]:'Not provided')}</strong></div><div class="metric"><span>Latest EBITDA found</span><strong>${esc(ebs.length?ebs[ebs.length-1]:'Not provided')}</strong></div><div class="metric"><span>Evidence status</span><strong>Unverified</strong></div></div>`;let list=(arr,fallback)=>`<ul>${(arr.length?arr:[fallback]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;let memo=`<div class="memo-paper"><div class="memo-top"><div><div class="memo-brand">MANDATE</div><div class="memo-label">Investment research · Working draft</div></div><div class="memo-label" style="text-align:right">${esc(audience)}<br/>CONFIDENTIAL · REVIEW REQUIRED</div></div><div class="memo-label">Investment memorandum</div><h2 class="memo-title">${esc(title)}</h2><div class="memo-meta">Prepared: ${new Date().toLocaleDateString()} &nbsp; | &nbsp; Sector: ${esc(sector)} &nbsp; | &nbsp; Geography: ${esc(geo)}<br/>Source: ${esc(activeFileName||'Pasted / sample source text')} &nbsp; | &nbsp; Draft depth: ${esc(depth)}</div>${metricCards}
<div class="memo-section"><h3>1. Executive summary</h3><p><strong>Preliminary status: Further diligence required.</strong> ${esc(company.slice(0,3).join(' ')||'The source materials describe an opportunity that requires additional review.')} The available materials are a starting point, not a recommendation. Key financial, market, management, valuation and transaction assumptions must be verified before an investment decision.</p><p><strong>Initial thesis to test:</strong> ${esc(thesis.slice(0,3).join(' ')||'The source has not yet established a fully supportable investment thesis. Identify the company’s differentiated advantage, durable demand, growth drivers and potential value-creation plan.')}</p></div>
<div class="memo-section"><h3>2. Business overview and business model</h3>${list(company,'Business description not provided. Confirm products/services, customer segments, revenue model, pricing, sales channels, customer acquisition, retention, unit economics and operating footprint.')}</div>
<div class="memo-section"><h3>3. Market opportunity and global landscape</h3>${list(market,'Market evidence is not available in the supplied source.')}<p>Required analysis: define TAM, SAM and SOM with transparent assumptions; size the market by geography and end market; document historical growth and forecast sources; assess customer demographics, purchasing behavior, regulation, technology shifts, trade flows and macro drivers. Distinguish third-party facts from management estimates.</p></div>
<div class="memo-section"><h3>4. Financial performance and projections</h3>${list(financials,'No clearly labeled historical financial metrics were extracted. Request three years of income statements, balance sheets, cash-flow statements and monthly management accounts.')}<p>Confirm reporting periods, units, currency, accounting basis, revenue recognition, gross margin, EBITDA adjustments, cash conversion, debt, working capital, maintenance and growth capex, burn rate if applicable, and forecast assumptions. Projections and key milestones were not independently built or validated by this browser prototype.</p></div>
<div class="memo-section"><h3>5. Competitive landscape and SWOT</h3>${list(competition,'No verified peer set or competitive data was identified.')}<p><strong>SWOT framework:</strong> Strengths and weaknesses should be supported by company evidence; opportunities and threats should be tied to sourced market trends, named competitors, customer feedback and regulatory changes. Do not infer market share without evidence.</p></div>
<div class="memo-section"><h3>6. Management and governance</h3>${list(management,'Management information not provided. Request biographies, role clarity, track record, references, incentives, ownership, board/governance structure, key-person exposure and succession plans.')}</div>
<div class="memo-section"><h3>7. Investment thesis and value creation plan</h3>${list(thesis,'The investment thesis is not yet substantiated. Test product differentiation, market position, customer economics, pricing power, organic growth, margin expansion, operational improvements and potential add-on acquisitions.')}<p>For each thesis point, attach evidence, an owner, a measurable KPI, a timeline and a disconfirming signal.</p></div>
<div class="memo-section"><h3>8. Key risks and mitigation</h3>${list(risks,'Identify and assess financial, market, customer, supplier, operational, regulatory, legal, technology, cybersecurity, management and execution risks.')}<p>For each material risk, document likelihood, impact, early-warning KPI, mitigation, accountable owner and residual exposure after mitigation.</p></div>
<div class="memo-section"><h3>9. Valuation, deal structure and returns</h3>${list(transaction,'Valuation methodology, investment size, ownership, security, dilution, governance, liquidation preferences, control rights, covenants and use of proceeds require confirmation.')}<p>Where data permits, compare relevant public peers and disclosed transactions on consistent LTM/NTM metrics. Document adjustments, net debt, leases, minority interests, working capital and sensitivity cases. Target returns, IRR/MOIC, dilution and waterfall are not calculated unless the required inputs are supplied.</p></div>
<div class="memo-section"><h3>10. Exit strategies</h3>${list(exit,'Consider strategic sale, sponsor-to-sponsor sale, recapitalization or public listing only where realistic for the company. Assess buyer universe, likely holding period, exit multiples, market cyclicality, debt repayment and proceeds waterfall.')}</div>
<div class="memo-section"><h3>11. Diligence plan and open questions</h3>${list(['Obtain audited financial statements, monthly management accounts and quality-of-earnings analysis.','Build customer and supplier concentration, retention, churn, pricing and gross-margin schedules.','Validate market sizing, growth forecasts and peer set using dated primary or reputable sources.','Review legal, regulatory, tax, compliance, IP, cybersecurity, environmental and employment matters as relevant.','Confirm management references, capex plan, working-capital needs, debt documents and downside liquidity.','Resolve valuation, ownership, investor rights, use of proceeds, exit assumptions and return waterfall.'],'Create a source-backed diligence tracker with priority, owner, due date and status.')}</div>
<div class="memo-section"><h3>12. Preliminary recommendation</h3><p><strong>Current conclusion: Do not treat this draft as an investment recommendation.</strong> Advance only to the next diligence stage if the opportunity fits mandate and initial source checks support the thesis. Record a clear proceed / pause / decline decision after key diligence gaps, valuation and downside risks are reviewed.</p></div>
<div class="memo-section"><h3>Sources, evidence status and limitations</h3><p>This draft is organized from user-supplied source text. No external market research, independent financial verification, management interviews, legal review or return underwriting was conducted by this generator. Automated extraction may misread values. Mark each factual claim as company-provided, independently sourced, calculated or unverified; attach source URL, publication date and relevant passage. Missing data is identified as a gap, not treated as fact.</p></div><div class="footnote">MANDATE · CONFIDENTIAL WORKING DRAFT · Not an offer, solicitation, investment recommendation, valuation opinion or commitment to invest.</div></div>`;currentMemo=memo;document.getElementById('memoOutput').innerHTML=memo;document.getElementById('memoCaption').textContent=`Structured investment memo draft generated from ${activeFileName||'provided text'} · verify facts, sources and financial figures before use.`;toast('Structured memo generated with market, team, SWOT, valuation, exit and diligence sections. Review all gaps.');}
