function sendResearchToMemo(subject,industry){const value=`RESEARCH DESK INPUT\nCompany: ${subject}\nIndustry: ${industry||subject}\n\nResearch workstreams to complete:\n- Market size, growth and forecast assumptions\n- Global landscape, regions and trade flows\n- Value chain, customer segments and pricing power\n- Competitive landscape and market shares\n- M&A activity and disclosed transaction terms\n- Public peers, financial performance and valuation\n- Regulation, technology and downside risks\n- Macro drivers, labor, input costs and capacity\n\nSource discipline: attach original URLs, publication dates and supporting passages. Distinguish verified facts, company claims, estimates and unanswered questions. No current facts have been verified by this browser-only research map.`;go('memo');const area=document.getElementById('memoText')||document.getElementById('memoInput')||document.getElementById('memoSourceText');if(area){area.value=(area.value?area.value+'\n\n':'')+value;toast('Research checklist added to Memo Studio.')}else{toast('Research checklist copied into the memo workflow notes; paste it into your memo source text.');copyText(value)}}
