function runIndustryResearch(){let sector=document.getElementById('researchSector').value.trim();let angle=document.getElementById('researchAngle').value;if(!sector){toast('Enter an industry or load the current deal first.');return}let q=encodeURIComponent(sector+' private equity M&A deals valuation news October 2026');let q2=encodeURIComponent(sector+' public company earnings investor presentation valuation');let q3=encodeURIComponent(sector+' regulatory industry outlook 2026');let current=(currentDeal&&currentDeal.sector&&sector.toLowerCase()===currentDeal.sector.toLowerCase())?currentDeal:null;let title=current?current.name+' · '+sector:sector;let focus=angle==='Recent M&A and sponsor activity'?'Map announced and closed transactions, sponsor-to-sponsor sales, add-on activity, buyer rationale, disclosed purchase multiples and financing structure.':angle==='Valuation and public-company comps'?'Build a peer set; compare EV/revenue, EV/EBITDA, growth, margins, leverage and estimate revisions on a consistent LTM/NTM basis.':angle==='Credit, rates and financing conditions'?'Review base rates, spreads, debt availability, leverage multiples, interest coverage, maturities, covenants and refinancing needs.':angle==='Regulatory and reimbursement risk'?'Check regulatory actions, reimbursement changes, antitrust, licensing, litigation, policy timelines and whether risk affects volume, pricing or exit options.':'Identify share shifts, customer concentration, pricing power, growth catalysts, capacity constraints and credible downside cases.';document.getElementById('industryBrief').innerHTML=`<div class="panelhead"><div><div class="eyebrow">Industry brief · research workplan</div><h3 class="paneltitle" style="margin-top:8px">${escapeHtml(title)}</h3><div class="paneldesc">${escapeHtml(angle)} · Prepared ${new Date().toLocaleDateString()}</div></div><button class="btn small" onclick="copyText(document.getElementById('briefCopy').innerText)">Copy brief</button></div><div id="briefCopy"><h4>What a PE analyst should know</h4><p style="line-height:1.75">${focus}</p><h4>Deal-specific diligence questions</h4><ul style="line-height:1.9"><li>What has changed in the last 90 days that could change the investment thesis or exit multiple?</li><li>Which announced deals have disclosed price, EBITDA/revenue, financing terms or strategic rationale? Separate disclosed facts from estimates.</li><li>How do public peers compare on organic growth, margins, leverage and valuation? Are adjustments comparable?</li><li>What are the two or three downside scenarios and which KPIs would signal that they are occurring?</li><li>What diligence claims need primary-source confirmation before being included in an investment committee memo?</li></ul></div><div class="divider"></div><div class="actions"><button class="btn" onclick="previewSource('pe')">Preview deal coverage ↗</button><button class="btn" onclick="previewSource('sec')">Preview company filings ↗</button><button class="btn" onclick="previewSource('health')">Preview regulatory releases ↗</button></div><div class="footnote">This is an analyst workplan, not a live AI-generated research conclusion. The source buttons open direct publisher pages; no current facts are claimed as verified by this prototype.</div>`}
function newsEscape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function loadLiveHeadlines(userInitiated=true){
 const query=(document.getElementById('liveNewsQuery')?.value||'private equity OR private credit OR M&A').trim()||'private equity OR private credit OR M&A';
 const days=document.getElementById('liveNewsWindow')?.value||'7';
 const external='https://news.google.com/search?q='+encodeURIComponent(query+' when:'+days+'d')+'&hl=en-US&gl=US&ceid=US:en';
 const externalEl=document.getElementById('liveNewsExternal');if(externalEl)externalEl.href=external;
 const root=document.getElementById('liveNewsResults'),meta=document.getElementById('liveNewsMeta');
 if(!root||!meta)return;
 root.innerHTML='<div class="empty"><strong>Loading current headlines…</strong>Connecting to a live news feed.</div>';
 meta.textContent='Searching live sources for: '+query+' · '+(days==='1'?'Past 24 hours':'Past '+days+' days');
 const rss='https://news.google.com/rss/search?q='+encodeURIComponent(query+' when:'+days+'d')+'&hl=en-US&gl=US&ceid=US:en';
 const endpoint='https://api.rss2json.com/v1/api.json?rss_url='+encodeURIComponent(rss);
 try{
  let records=[];
  try{
   const response=await fetch(endpoint,{headers:{'Accept':'application/json'}});
   if(!response.ok)throw new Error('RSS conversion request failed');
   const data=await response.json();
   if(data.status!=='ok'||!Array.isArray(data.items)||!data.items.length)throw new Error('No results from first feed service');
   records=data.items;
  }catch(firstError){
   const proxy='https://api.allorigins.win/raw?url='+encodeURIComponent(rss);
   const response=await fetch(proxy,{headers:{'Accept':'application/xml,text/xml,*/*'}});
   if(!response.ok)throw new Error('Live RSS sources could not be reached');
   const xmlText=await response.text();
   const doc=new DOMParser().parseFromString(xmlText,'text/xml');
   records=Array.from(doc.querySelectorAll('item')).map(node=>({title:node.querySelector('title')?.textContent||'Untitled headline',link:node.querySelector('link')?.textContent||external,author:node.querySelector('source')?.textContent||'Google News',pubDate:node.querySelector('pubDate')?.textContent||''}));
   if(!records.length)throw new Error('The live feed returned no headlines');
  }
  root.innerHTML=records.slice(0,10).map(item=>{
   let url=String(item.link||'');if(!/^https?:\/\//i.test(url))url=external;
   const pub=String(item.author||item.source||'Google News');
   const date=item.pubDate?new Date(item.pubDate):null;
   const dateText=date&&!Number.isNaN(date.getTime())?date.toLocaleString():'Publication date unavailable';
   return `<article class="sample research-result-card"><div class="sampletext"><strong>${newsEscape(item.title||'Untitled headline')}</strong><span>${newsEscape(pub)} · ${newsEscape(dateText)}</span><div class="smallmuted" style="margin-top:5px">Live discovery result · verify details at the original publisher</div></div><a class="btn small primary research-open" href="${newsEscape(url)}" target="_blank" rel="noopener">Read ↗</a></article>`;
  }).join('');
  meta.textContent='Live feed · refreshed '+new Date().toLocaleString()+' · '+records.length+' headlines returned · '+query;
 }catch(err){
  root.innerHTML=`<div class="empty"><strong>Live headlines could not load inside this preview.</strong>The feed connection can depend on browser access and third-party availability. Open the live search to see current results, rather than relying on cached or invented headlines.<div class="actions" style="margin-top:12px"><a class="btn primary" href="${newsEscape(external)}" target="_blank" rel="noopener">Open current news results ↗</a><button class="btn" onclick="loadLiveHeadlines(true)">Try again ↻</button></div></div>`;
  meta.textContent='Live feed connection unavailable · direct live search is available';
 }
}
