let secSearchBusy=false;
function secEscape(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function secFilingUrl(hit){
 const src=hit?._source||{};
 const cik=Array.isArray(src.ciks)?String(src.ciks[0]||'').replace(/^0+/, ''):String(src.cik||'').replace(/^0+/, '');
 const accession=String(src.adsh||src.accession_no||'').replace(/-/g,'');
 const primary=String(src.file_name||src.primary_doc||src.primaryDocument||'');
 if(cik && accession && primary && !primary.includes('/') && !primary.includes('..')) return `https://www.sec.gov/Archives/edgar/data/${cik}/${accession}/${encodeURIComponent(primary)}`;
 return 'https://www.sec.gov/edgar/search/';
}
function renderSecResults(hits,query){
 const out=document.getElementById('secSearchResults');
 if(!hits.length){out.innerHTML='<div class="sec-results-empty">No matching filings were returned for this query. Try a ticker, company name, or broader keyword. You can also open the official SEC search page.</div>';return;}
 out.innerHTML=hits.slice(0,12).map(hit=>{const d=hit?._source||{};const name=(d.display_names&&d.display_names[0])||d.entity_name||d.company_name||'SEC filing';const form=d.form_type||d.file_type||d.root_forms||'Filing';const date=d.file_date||d.filing_date||'';const period=d.period_of_report||'';const desc=d.file_description||d.description||'';const url=secFilingUrl(hit);return `<article class="sec-result"><div class="sec-result-top"><div><h4>${secEscape(name)}</h4><p>${secEscape(desc||'Official SEC filing')} ${period?'· Reporting period: '+secEscape(period):''}</p></div><span class="badge">${secEscape(Array.isArray(form)?form.join(', '):form)}</span></div><p>Filing date: ${secEscape(date||'Date not supplied by search index')}</p><a href="${url}" target="_blank" rel="noopener">Open original filing ↗</a> <span style="color:#8a958d;font-size:10px">·</span> <a href="https://www.sec.gov/edgar/search/#/q=${encodeURIComponent(query)}" target="_blank" rel="noopener">View in EDGAR ↗</a></article>`}).join('');
}
async function searchSecFilings(){
 const input=document.getElementById('secQuery');const query=input.value.trim();const form=document.getElementById('secForm').value;const status=document.getElementById('secSearchStatus');const button=document.getElementById('secSearchButton');const out=document.getElementById('secSearchResults');
 if(!query){status.textContent='Enter a company, ticker or keyword first.';input.focus();return;}
 const officialUrl='https://www.sec.gov/edgar/search/#/q='+encodeURIComponent(query)+(form?'&forms='+encodeURIComponent(form):'');document.getElementById('secExternalSearch').href=officialUrl;
 status.textContent='Searching SEC EDGAR…';out.innerHTML='';button.disabled=true;button.textContent='Searching…';
 try{
  const params=new URLSearchParams({q:query,dateRange:'custom',startdt:'2020-01-01',enddt:new Date().toISOString().slice(0,10)});if(form)params.set('forms',form);
  const response=await fetch('https://efts.sec.gov/LATEST/search-index?'+params.toString(),{headers:{'Accept':'application/json'}});
  if(!response.ok)throw new Error('SEC search returned HTTP '+response.status);
  const data=await response.json();const hits=data?.hits?.hits||data?.hits||[];renderSecResults(Array.isArray(hits)?hits:[],query);
  status.textContent=`SEC search completed · ${hits.length} result${hits.length===1?'':'s'} returned · Retrieved ${new Date().toLocaleString()}.`;
 }catch(err){
  status.textContent='The live result request was blocked or unavailable in this browser. Use the official SEC EDGAR search link below; it searches the same public filing database.';
  const googleUrl='https://www.google.com/search?q='+encodeURIComponent('site:sec.gov/Archives/edgar/data "'+query+'" '+(form||''));const newsUrl='https://news.google.com/search?q='+encodeURIComponent('"'+query+'" company earnings OR acquisition OR filing');out.innerHTML=`<div class="sec-results-empty"><strong>Live search links are ready.</strong><br/>The SEC's result API could not be read inside this browser. To avoid showing fake results, use one of these live searches instead.<div class="actions" style="margin-top:12px"><a class="btn primary small" href="${officialUrl}" target="_blank" rel="noopener">Search SEC EDGAR ↗</a><a class="btn small" href="${googleUrl}" target="_blank" rel="noopener">Search SEC documents ↗</a><a class="btn small" href="${newsUrl}" target="_blank" rel="noopener">Company news ↗</a></div></div>`;
 }
 button.disabled=false;button.textContent='Search official filings →';
}
